<?php
namespace App\Filament\Resources;
use Filament\Resources\Resource;
use Filament\Schemas\Schema;
use Filament\Tables\Table;
use Filament\Forms\Components\{TextInput,Textarea,Select,Toggle,DateTimePicker,DatePicker};
use Filament\Tables\Columns\TextColumn;
use Filament\Actions\EditAction;
class StandResource extends Resource {
 protected static ?string $model=\App\Models\Stand::class;
 protected static ?string $modelLabel='Stands et emplacements';
 protected static ?string $pluralModelLabel='Stands et emplacements';
 protected static string|\UnitEnum|null $navigationGroup='4 · Préparer';

 protected static ?int $navigationSort=50;

 public static function form(Schema $schema): Schema {return $schema->columns(2)->components([Select::make('event_project_id')->label('Édition')->relationship('eventProject','name')->preload()->searchable()->required()->disabledOn('edit'),TextInput::make('name')->label('Stand')->required()->maxLength(120),TextInput::make('freguesia')->label('Freguesia (vide tant que non identifiée)')->maxLength(120),Textarea::make('specialty')->label('Spécialité du village et produits proposés')->maxLength(5000),Textarea::make('sales_staff')->label('Équipe de vente pendant les épreuves')->maxLength(3000),TextInput::make('shelter_target')->label('Objectif de personnes abritées')->integer()->minValue(1)->maxValue(10000)->default(24)->required(),TextInput::make('sheltered_capacity')->label('Capacité abritée vérifiée')->integer()->minValue(0),TextInput::make('seated_capacity')->label('Places assises vérifiées')->integer()->minValue(0)->helperText('24 abritées / 12 assises : un ensemble inclus = 6 places ; compléter avec un second ensemble ou du mobilier propre/prêté. Préserver l’espace debout et les circulations.'),TextInput::make('included_furniture_sets')->label('Ensembles six places inclus')->integer()->minValue(0)->default(1)->required(),TextInput::make('extra_furniture_sets')->label('Ensembles six places optionnels')->integer()->minValue(0)->default(0)->required(),Select::make('shelter_source')->label('Provenance de la tente')->options(['undecided'=>'À définir','own'=>'Apport exposant','loan'=>'Prêt documenté','qapas'=>'Fourniture QAPAS à chiffrer'])->default('undecided')->required(),Toggle::make('larger_tent_requested')->label('Tente plus grande demandée, supplément à chiffrer'),Textarea::make('hospitality_evidence')->label('Plan d’accueil, debout/assis, circulations, dimensions, devis et apports'),Toggle::make('hospitality_validated')->label('Plan d’accueil vérifié après enregistrement')->helperText('Toute modification des capacités ou du mobilier impose une nouvelle validation.'),Toggle::make('direct_costs_complete')->label('Coûts directs de l’offre QAPAS recensés'),Select::make('site_feature_id')->label('Objet sur le plan géographique')->relationship('siteFeature','name'),Select::make('kind')->label('Type')->options(['village'=>'Équipe de freguesia','independent'=>'Exposant indépendant'])->required(),TextInput::make('operator')->label('Exploitant / cocontractant à vérifier')->maxLength(255),TextInput::make('zone')->label('Zone proposée')->maxLength(120),Select::make('structure')->label('Structure')->options(['bare'=>'Emplacement nu','provided'=>'Structure fournie'])->required(),Select::make('status')->label('Préparation')->options(['proposed'=>'Proposé','reviewing'=>'Dossier en revue','planned'=>'Implantation prévue','withdrawn'=>'Retiré'])->required(),Textarea::make('needs')->label('Besoins, accès, électricité, activités, coexposants')->maxLength(5000)->columnSpanFull(),Textarea::make('material_support')->label('Aide affectée et justificatifs · hors recettes libres')->maxLength(5000)->columnSpanFull()]);}
 public static function table(Table $table): Table {return $table->columns([TextColumn::make('name')->label('Nom')->searchable()->wrap(),TextColumn::make('eventProject.name')->label('Édition'),TextColumn::make('status')->label('État')->badge(),TextColumn::make('updated_at')->label('Mise à jour')->dateTime('d/m/Y H:i')->sortable()])->defaultSort('updated_at','desc')->recordActions([EditAction::make()]);}
 public static function getPages(): array {return ['index'=>\App\Filament\Resources\StandResource\Pages\ManageRecords::route('/')];}
}
